window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d1399657d6a9954a"]={"versions": [{"id": "FIG-d1399657d6a9954a", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Templates, Releases R3.0.7 / R3.1.5).\n</li><li><strong>Architektur-Kontext:</strong> Spezifikation von Übertragungsmustern ereignisgesteuerter Kommunikationsbeziehungen (I-PDU- und Frame-Ebene) im Kommunikations-Cluster (CAN, LIN, FlexRay). Es definiert die Wiederholcharakteristik bei getriggerten Sendeereignissen vor der Transformation in BSW-Generatorkonfigurationen (insb. <code>Com</code>-Stack).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code> (Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Definiert das Zeitverhalten einer ereignisbasierten Transmission.\n</li><li>Attribut <code>+ numberOfRepeats: Int</code>: Anzahl der zusätzlichen Wiederholungen eines I-PDUs nach dem initialen Ereignis-Trigger (<code>0</code> = keine Wiederholung, nur Einzelsendung; <code>n &gt; 0</code> = <code>n</code> Wiederholungen).\n</li></ul>\n</li><li><strong><code>TimeRangeType</code> (Strukturtyp):</strong>\n<ul class=\"fig-list\"><li>Aggregiert über gerichtete Komposition (<code>+repetitionPeriod</code>, Kardinalität <code>1</code>).\n</li><li>Attribut <code>+ value: Float</code>: Physikalischer Basiswert der Wiederholperiode (in Sekunden).\n</li></ul>\n</li><li><strong><code>TimeRangeTypeTolerance</code> (Abstrakte Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimeRangeType</code> über gerichtete Komposition (<code>+tolerance</code>, Kardinalität <code>0..1</code>).\n</li><li>Dient als polymorphe Basis für Toleranzangaben.\n</li></ul>\n</li><li><strong><code>RelativeTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ relative: Int</code>: Prozentuale Abweichung bezogen auf <code>value</code> (z. B. Jitter-Toleranz).\n</li></ul>\n</li><li><strong><code>AbsoluteTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ absolute: Float</code>: Absolute zeitliche Abweichung in Sekunden ($\\pm \\Delta t$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Eine Applikations-SWC aktualisiert ein Signal via RTE mit Übertragungseigenschaft <code>TRIGGERED</code> oder <code>TRIGGERED_WITHOUT_REPETITION</code>.\n</li><li><strong>Sendeabfolge:</strong>\n<ol class=\"fig-list\"><li>Initialer Sendeaufruf (<code>PduR_ComTransmit</code> bzw. <code>Com_SendSignal</code>) triggert die erste PDU-Übertragung.\n</li><li>Ist <code>numberOfRepeats &gt; 0</code>, startet der COM-Stack einen internen zyklischen Wiederholungs-Timer mit Intervall T_rep = repetitionPeriod.value ± tolerance.\n</li><li>Nach Ablauf von T_rep erfolgt die nächste Aussendung, bis exakt <code>numberOfRepeats</code> Folgeübertragungen abgesetzt wurden.\n</li><li>Trifft während eines laufenden Wiederholungszyklus ein erneutes Event ein, wird der Wiederholzähler gemäß COM-Filter-/Übertragungssemantik entweder re-triggert oder verworfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Transformation in BSW-Konfiguration (COM):</strong>\n<ul class=\"fig-list\"><li>Entspricht direkt den Parametern des BSW-Moduls <code>Com</code> (in R4.x refaktoriert zu <code>ComTxModeNumberOfRepetitions</code> und <code>ComTxModeRepetitionPeriod</code> innerhalb von <code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li></ul>\n</li><li><strong>Timing-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><code>TimeRangeType.value</code> muss auf ein ganzzahliges Vielfaches des BSW-Zyklus (<code>Com_MainFunctionTx</code> Raster) abgebildet werden. Abweichungen müssen innerhalb der spezifizierten <code>tolerance</code> (absolut oder relativ) liegen, andernfalls drohen Konfigurationswarnungen oder Jitter im Sende-Task.\n</li></ul>\n</li><li><strong>PDU-Priorisierung &amp; Buslast:</strong>\n<ul class=\"fig-list\"><li>Hohe <code>numberOfRepeats</code>-Werte bei hochfrequenten Events führen zu Bus-Burst-Zuständen und können die Minimum Delay Time (<code>ComMinimumDelayTime</code> / <code>MinimunDelayTime</code>) verletzen, falls diese nicht konsistent mit <code>repetitionPeriod</code> parametriert ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f79e0a688065fc8b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Templates, Release R3.2.3).\n</li><li><strong>Architektur-Kontext:</strong> Spezifikation von Übertragungsmustern ereignisgesteuerter Kommunikationsbeziehungen (I-PDU- und Frame-Ebene) im Kommunikations-Cluster (CAN, LIN, FlexRay). Es definiert die Wiederholcharakteristik bei getriggerten Sendeereignissen vor der Transformation in BSW-Generatorkonfigurationen (insb. <code>Com</code>-Stack).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code> (Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Definiert das Zeitverhalten einer ereignisbasierten Transmission.\n</li><li>Attribut <code>+ numberOfRepeats: Integer</code>: Anzahl der zusätzlichen Wiederholungen eines I-PDUs nach dem initialen Ereignis-Trigger (<code>0</code> = keine Wiederholung, nur Einzelsendung; <code>n &gt; 0</code> = <code>n</code> Wiederholungen).\n</li></ul>\n</li><li><strong><code>TimeRangeType</code> (Strukturtyp):</strong>\n<ul class=\"fig-list\"><li>Aggregiert über gerichtete Komposition (<code>+repetitionPeriod</code>, Kardinalität <code>0..1</code>).\n</li><li>Attribut <code>+ value: Float</code>: Physikalischer Basiswert der Wiederholperiode (in Sekunden).\n</li></ul>\n</li><li><strong><code>TimeRangeTypeTolerance</code> (Abstrakte Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimeRangeType</code> über gerichtete Komposition (<code>+tolerance</code>, Kardinalität <code>0..1</code>).\n</li><li>Dient als polymorphe Basis für Toleranzangaben.\n</li></ul>\n</li><li><strong><code>RelativeTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ relative: Integer</code>: Prozentuale Abweichung bezogen auf <code>value</code> (z. B. Jitter-Toleranz).\n</li></ul>\n</li><li><strong><code>AbsoluteTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ absolute: Float</code>: Absolute zeitliche Abweichung in Sekunden ($\\pm \\Delta t$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Eine Applikations-SWC aktualisiert ein Signal via RTE mit Übertragungseigenschaft <code>TRIGGERED</code> oder <code>TRIGGERED_WITHOUT_REPETITION</code>.\n</li><li><strong>Sendeabfolge:</strong>\n<ol class=\"fig-list\"><li>Initialer Sendeaufruf (<code>PduR_ComTransmit</code> bzw. <code>Com_SendSignal</code>) triggert die erste PDU-Übertragung.\n</li><li>Ist <code>numberOfRepeats &gt; 0</code>, startet der COM-Stack einen internen zyklischen Wiederholungs-Timer mit Intervall T_rep = repetitionPeriod.value ± tolerance.\n</li><li>Nach Ablauf von T_rep erfolgt die nächste Aussendung, bis exakt <code>numberOfRepeats</code> Folgeübertragungen abgesetzt wurden.\n</li><li>Trifft während eines laufenden Wiederholungszyklus ein erneutes Event ein, wird der Wiederholzähler gemäß COM-Filter-/Übertragungssemantik entweder re-triggert oder verworfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Transformation in BSW-Konfiguration (COM):</strong>\n<ul class=\"fig-list\"><li>Entspricht direkt den Parametern des BSW-Moduls <code>Com</code> (in R4.x refaktoriert zu <code>ComTxModeNumberOfRepetitions</code> und <code>ComTxModeRepetitionPeriod</code> innerhalb von <code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li></ul>\n</li><li><strong>Timing-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><code>TimeRangeType.value</code> muss auf ein ganzzahliges Vielfaches des BSW-Zyklus (<code>Com_MainFunctionTx</code> Raster) abgebildet werden. Abweichungen müssen innerhalb der spezifizierten <code>tolerance</code> (absolut oder relativ) liegen, andernfalls drohen Konfigurationswarnungen oder Jitter im Sende-Task.\n</li></ul>\n</li><li><strong>PDU-Priorisierung &amp; Buslast:</strong>\n<ul class=\"fig-list\"><li>Hohe <code>numberOfRepeats</code>-Werte bei hochfrequenten Events führen zu Bus-Burst-Zuständen und können die Minimum Delay Time (<code>ComMinimumDelayTime</code> / <code>MinimunDelayTime</code>) verletzen, falls diese nicht konsistent mit <code>repetitionPeriod</code> parametriert ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d3a69ed97630c286", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Templates, Release R4.0.3).\n</li><li><strong>Architektur-Kontext:</strong> Spezifikation von Übertragungsmustern ereignisgesteuerter Kommunikationsbeziehungen (I-PDU- und Frame-Ebene) im Kommunikations-Cluster (CAN, LIN, FlexRay). Es definiert die Wiederholcharakteristik bei getriggerten Sendeereignissen vor der Transformation in BSW-Generatorkonfigurationen (insb. <code>Com</code>-Stack).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code> (Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Definiert das Zeitverhalten einer ereignisbasierten Transmission.\n</li><li>Attribut <code>+ numberOfRepetitions: Integer</code>: Anzahl der zusätzlichen Wiederholungen eines I-PDUs nach dem initialen Ereignis-Trigger (<code>0</code> = keine Wiederholung, nur Einzelsendung; <code>n &gt; 0</code> = <code>n</code> Wiederholungen).\n</li></ul>\n</li><li><strong><code>TimeRangeType</code> (Strukturtyp):</strong>\n<ul class=\"fig-list\"><li>Aggregiert über gerichtete Komposition (<code>+repetitionPeriod</code>, Kardinalität <code>0..1</code>).\n</li><li>Attribut <code>+ value: TimeValue</code>: Physikalischer Basiswert der Wiederholperiode als standardisierter Zeitwert.\n</li></ul>\n</li><li><strong><code>TimeRangeTypeTolerance</code> (Abstrakte Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimeRangeType</code> über gerichtete Komposition (<code>+tolerance</code>, Kardinalität <code>0..1</code>).\n</li><li>Dient als polymorphe Basis für Toleranzangaben.\n</li></ul>\n</li><li><strong><code>RelativeTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ relative: Integer</code>: Prozentuale Abweichung bezogen auf <code>value</code> (z. B. Jitter-Toleranz).\n</li></ul>\n</li><li><strong><code>AbsoluteTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ absolute: TimeValue</code>: Absolute zeitliche Abweichung als standardisierter Zeitwert ($\\pm \\Delta t$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Eine Applikations-SWC aktualisiert ein Signal via RTE mit Übertragungseigenschaft <code>TRIGGERED</code> oder <code>TRIGGERED_WITHOUT_REPETITION</code>.\n</li><li><strong>Sendeabfolge:</strong>\n<ol class=\"fig-list\"><li>Initialer Sendeaufruf (<code>PduR_ComTransmit</code> bzw. <code>Com_SendSignal</code>) triggert die erste PDU-Übertragung.\n</li><li>Ist <code>numberOfRepetitions &gt; 0</code>, startet der COM-Stack einen internen zyklischen Wiederholungs-Timer mit Intervall T_rep = repetitionPeriod.value ± tolerance.\n</li><li>Nach Ablauf von T_rep erfolgt die nächste Aussendung, bis exakt <code>numberOfRepetitions</code> Folgeübertragungen abgesetzt wurden.\n</li><li>Trifft während eines laufenden Wiederholungszyklus ein erneutes Event ein, wird der Wiederholzähler gemäß COM-Filter-/Übertragungssemantik entweder re-triggert oder verworfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Transformation in BSW-Konfiguration (COM):</strong>\n<ul class=\"fig-list\"><li>Entspricht direkt den Parametern des BSW-Moduls <code>Com</code> (<code>ComTxModeNumberOfRepetitions</code> und <code>ComTxModeRepetitionPeriod</code> innerhalb von <code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li></ul>\n</li><li><strong>Timing-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><code>TimeRangeType.value</code> muss auf ein ganzzahliges Vielfaches des BSW-Zyklus (<code>Com_MainFunctionTx</code> Raster) abgebildet werden. Abweichungen müssen innerhalb der spezifizierten <code>tolerance</code> (absolut oder relativ) liegen, andernfalls drohen Konfigurationswarnungen oder Jitter im Sende-Task.\n</li></ul>\n</li><li><strong>PDU-Priorisierung &amp; Buslast:</strong>\n<ul class=\"fig-list\"><li>Hohe <code>numberOfRepetitions</code>-Werte bei hochfrequenten Events führen zu Bus-Burst-Zuständen und können die Minimum Delay Time (<code>ComMinimumDelayTime</code>) verletzen, falls diese nicht konsistent mit <code>repetitionPeriod</code> parametriert ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a8bba802d8b91b6e", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Templates, Release R4.1.3).\n</li><li><strong>Architektur-Kontext:</strong> Spezifikation von Übertragungsmustern ereignisgesteuerter Kommunikationsbeziehungen (I-PDU- und Frame-Ebene) im Kommunikations-Cluster (CAN, LIN, FlexRay). Es definiert die Wiederholcharakteristik bei getriggerten Sendeereignissen vor der Transformation in BSW-Generatorkonfigurationen (insb. <code>Com</code>-Stack).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code> (Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Erbt von <code>Describable</code> zur Dokumentation und textuellen Beschreibung des Timing-Elements.\n</li><li>Definiert das Zeitverhalten einer ereignisbasierten Transmission.\n</li><li>Attribut <code>+ numberOfRepetitions: Integer</code>: Anzahl der zusätzlichen Wiederholungen eines I-PDUs nach dem initialen Ereignis-Trigger (<code>0</code> = keine Wiederholung, nur Einzelsendung; <code>n &gt; 0</code> = <code>n</code> Wiederholungen).\n</li></ul>\n</li><li><strong><code>TimeRangeType</code> (Strukturtyp):</strong>\n<ul class=\"fig-list\"><li>Aggregiert über gerichtete Komposition (<code>+repetitionPeriod</code>, Kardinalität <code>0..1</code>).\n</li><li>Attribut <code>+ value: TimeValue</code>: Physikalischer Basiswert der Wiederholperiode als standardisierter Zeitwert.\n</li></ul>\n</li><li><strong><code>TimeRangeTypeTolerance</code> (Abstrakte Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimeRangeType</code> über gerichtete Komposition (<code>+tolerance</code>, Kardinalität <code>0..1</code>).\n</li><li>Dient als polymorphe Basis für Toleranzangaben.\n</li></ul>\n</li><li><strong><code>RelativeTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ relative: Integer</code>: Prozentuale Abweichung bezogen auf <code>value</code> (z. B. Jitter-Toleranz).\n</li></ul>\n</li><li><strong><code>AbsoluteTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ absolute: TimeValue</code>: Absolute zeitliche Abweichung als standardisierter Zeitwert ($\\pm \\Delta t$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Eine Applikations-SWC aktualisiert ein Signal via RTE mit Übertragungseigenschaft <code>TRIGGERED</code> oder <code>TRIGGERED_WITHOUT_REPETITION</code>.\n</li><li><strong>Sendeabfolge:</strong>\n<ol class=\"fig-list\"><li>Initialer Sendeaufruf (<code>PduR_ComTransmit</code> bzw. <code>Com_SendSignal</code>) triggert die erste PDU-Übertragung.\n</li><li>Ist <code>numberOfRepetitions &gt; 0</code>, startet der COM-Stack einen internen zyklischen Wiederholungs-Timer mit Intervall T_rep = repetitionPeriod.value ± tolerance.\n</li><li>Nach Ablauf von T_rep erfolgt die nächste Aussendung, bis exakt <code>numberOfRepetitions</code> Folgeübertragungen abgesetzt wurden.\n</li><li>Trifft während eines laufenden Wiederholungszyklus ein erneutes Event ein, wird der Wiederholzähler gemäß COM-Filter-/Übertragungssemantik entweder re-triggert oder verworfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Transformation in BSW-Konfiguration (COM):</strong>\n<ul class=\"fig-list\"><li>Entspricht direkt den Parametern des BSW-Moduls <code>Com</code> (<code>ComTxModeNumberOfRepetitions</code> und <code>ComTxModeRepetitionPeriod</code> innerhalb von <code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li></ul>\n</li><li><strong>Timing-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><code>TimeRangeType.value</code> muss auf ein ganzzahliges Vielfaches des BSW-Zyklus (<code>Com_MainFunctionTx</code> Raster) abgebildet werden. Abweichungen müssen innerhalb der spezifizierten <code>tolerance</code> (absolut oder relativ) liegen, andernfalls drohen Konfigurationswarnungen oder Jitter im Sende-Task.\n</li></ul>\n</li><li><strong>PDU-Priorisierung &amp; Buslast:</strong>\n<ul class=\"fig-list\"><li>Hohe <code>numberOfRepetitions</code>-Werte bei hochfrequenten Events führen zu Bus-Burst-Zuständen und können die Minimum Delay Time (<code>ComMinimumDelayTime</code>) verletzen, falls diese nicht konsistent mit <code>repetitionPeriod</code> parametriert ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8361984e889c0ac3", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Templates, Releases R4.2.2 / R4.3.1).\n</li><li><strong>Architektur-Kontext:</strong> Spezifikation von Übertragungsmustern ereignisgesteuerter Kommunikationsbeziehungen (I-PDU- und Frame-Ebene) im Kommunikations-Cluster (CAN, LIN, FlexRay). Es definiert die Wiederholcharakteristik bei getriggerten Sendeereignissen vor der Transformation in BSW-Generatorkonfigurationen (insb. <code>Com</code>-Stack).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code> (Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Erbt von <code>Describable</code> zur Dokumentation und textuellen Beschreibung des Timing-Elements.\n</li><li>Definiert das Zeitverhalten einer ereignisbasierten Transmission.\n</li><li>Attribut <code>+ numberOfRepetitions: Integer</code>: Anzahl der zusätzlichen Wiederholungen eines I-PDUs nach dem initialen Ereignis-Trigger (<code>0</code> = keine Wiederholung, nur Einzelsendung; <code>n &gt; 0</code> = <code>n</code> Wiederholungen).\n</li></ul>\n</li><li><strong><code>TimeRangeType</code> (Strukturtyp):</strong>\n<ul class=\"fig-list\"><li>Aggregiert über gerichtete Komposition (<code>+repetitionPeriod</code>, Kardinalität <code>0..1</code>).\n</li><li>Attribut <code>+ value: TimeValue</code>: Physikalischer Basiswert der Wiederholperiode als standardisierter Zeitwert.\n</li></ul>\n</li><li><strong><code>TimeRangeTypeTolerance</code> (Abstrakte Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimeRangeType</code> über gerichtete Komposition (<code>+tolerance</code>, Kardinalität <code>0..1</code>).\n</li><li>Dient als polymorphe Basis für Toleranzangaben.\n</li></ul>\n</li><li><strong><code>RelativeTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ relative: Integer</code>: Prozentuale Abweichung bezogen auf <code>value</code> (z. B. Jitter-Toleranz).\n</li></ul>\n</li><li><strong><code>AbsoluteTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ absolute: TimeValue</code>: Absolute zeitliche Abweichung als standardisierter Zeitwert ($\\pm \\Delta t$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Eine Applikations-SWC aktualisiert ein Signal via RTE mit Übertragungseigenschaft <code>TRIGGERED</code> oder <code>TRIGGERED_WITHOUT_REPETITION</code>.\n</li><li><strong>Sendeabfolge:</strong>\n<ol class=\"fig-list\"><li>Initialer Sendeaufruf (<code>PduR_ComTransmit</code> bzw. <code>Com_SendSignal</code>) triggert die erste PDU-Übertragung.\n</li><li>Ist <code>numberOfRepetitions &gt; 0</code>, startet der COM-Stack einen internen zyklischen Wiederholungs-Timer mit Intervall T_rep = repetitionPeriod.value ± tolerance.\n</li><li>Nach Ablauf von T_rep erfolgt die nächste Aussendung, bis exakt <code>numberOfRepetitions</code> Folgeübertragungen abgesetzt wurden.\n</li><li>Trifft während eines laufenden Wiederholungszyklus ein erneutes Event ein, wird der Wiederholzähler gemäß COM-Filter-/Übertragungssemantik entweder re-triggert oder verworfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Transformation in BSW-Konfiguration (COM):</strong>\n<ul class=\"fig-list\"><li>Entspricht direkt den Parametern des BSW-Moduls <code>Com</code> (<code>ComTxModeNumberOfRepetitions</code> und <code>ComTxModeRepetitionPeriod</code> innerhalb von <code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li></ul>\n</li><li><strong>Timing-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><code>TimeRangeType.value</code> muss auf ein ganzzahliges Vielfaches des BSW-Zyklus (<code>Com_MainFunctionTx</code> Raster) abgebildet werden. Abweichungen müssen innerhalb der spezifizierten <code>tolerance</code> (absolut oder relativ) liegen, andernfalls drohen Konfigurationswarnungen oder Jitter im Sende-Task.\n</li></ul>\n</li><li><strong>PDU-Priorisierung &amp; Buslast:</strong>\n<ul class=\"fig-list\"><li>Hohe <code>numberOfRepetitions</code>-Werte bei hochfrequenten Events führen zu Bus-Burst-Zuständen und können die Minimum Delay Time (<code>ComMinimumDelayTime</code>) verletzen, falls diese nicht konsistent mit <code>repetitionPeriod</code> parametriert ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c416955f9b8dbb27", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Templates, Releases R18-10, R19-11, R20-11).\n</li><li><strong>Architektur-Kontext:</strong> Spezifikation von Übertragungsmustern ereignisgesteuerter Kommunikationsbeziehungen (I-PDU- und Frame-Ebene) im Kommunikations-Cluster (CAN, LIN, FlexRay). Es definiert die Wiederholcharakteristik bei getriggerten Sendeereignissen vor der Transformation in BSW-Generatorkonfigurationen (insb. <code>Com</code>-Stack).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code> (Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Erbt von <code>Describable</code> zur Dokumentation und textuellen Beschreibung des Timing-Elements.\n</li><li>Definiert das Zeitverhalten einer ereignisbasierten Transmission.\n</li><li>Attribut <code>+ numberOfRepetitions: Integer</code>: Anzahl der zusätzlichen Wiederholungen eines I-PDUs nach dem initialen Ereignis-Trigger (<code>0</code> = keine Wiederholung, nur Einzelsendung; <code>n &gt; 0</code> = <code>n</code> Wiederholungen).\n</li></ul>\n</li><li><strong><code>TimeRangeType</code> (Strukturtyp):</strong>\n<ul class=\"fig-list\"><li>Aggregiert über gerichtete Komposition (<code>+repetitionPeriod</code>, Kardinalität <code>0..1</code>).\n</li><li>Attribut <code>+ value: TimeValue</code>: Physikalischer Basiswert der Wiederholperiode als standardisierter Zeitwert.\n</li></ul>\n</li><li><strong><code>TimeRangeTypeTolerance</code> (Abstrakte Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimeRangeType</code> über gerichtete Komposition (<code>+tolerance</code>, Kardinalität <code>0..1</code>).\n</li><li>Dient als polymorphe Basis für Toleranzangaben.\n</li></ul>\n</li><li><strong><code>RelativeTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ relative: Integer</code>: Prozentuale Abweichung bezogen auf <code>value</code> (z. B. Jitter-Toleranz).\n</li></ul>\n</li><li><strong><code>AbsoluteTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ absolute: TimeValue</code>: Absolute zeitliche Abweichung als standardisierter Zeitwert ($\\pm \\Delta t$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Eine Applikations-SWC aktualisiert ein Signal via RTE mit Übertragungseigenschaft <code>TRIGGERED</code> oder <code>TRIGGERED_WITHOUT_REPETITION</code>.\n</li><li><strong>Sendeabfolge:</strong>\n<ol class=\"fig-list\"><li>Initialer Sendeaufruf (<code>PduR_ComTransmit</code> bzw. <code>Com_SendSignal</code>) triggert die erste PDU-Übertragung.\n</li><li>Ist <code>numberOfRepetitions &gt; 0</code>, startet der COM-Stack einen internen zyklischen Wiederholungs-Timer mit Intervall T_rep = repetitionPeriod.value ± tolerance.\n</li><li>Nach Ablauf von T_rep erfolgt die nächste Aussendung, bis exakt <code>numberOfRepetitions</code> Folgeübertragungen abgesetzt wurden.\n</li><li>Trifft während eines laufenden Wiederholungszyklus ein erneutes Event ein, wird der Wiederholzähler gemäß COM-Filter-/Übertragungssemantik entweder re-triggert oder verworfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Transformation in BSW-Konfiguration (COM):</strong>\n<ul class=\"fig-list\"><li>Entspricht direkt den Parametern des BSW-Moduls <code>Com</code> (<code>ComTxModeNumberOfRepetitions</code> und <code>ComTxModeRepetitionPeriod</code> innerhalb von <code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li></ul>\n</li><li><strong>Timing-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><code>TimeRangeType.value</code> muss auf ein ganzzahliges Vielfaches des BSW-Zyklus (<code>Com_MainFunctionTx</code> Raster) abgebildet werden. Abweichungen müssen innerhalb der spezifizierten <code>tolerance</code> (absolut oder relativ) liegen, andernfalls drohen Konfigurationswarnungen oder Jitter im Sende-Task.\n</li></ul>\n</li><li><strong>PDU-Priorisierung &amp; Buslast:</strong>\n<ul class=\"fig-list\"><li>Hohe <code>numberOfRepetitions</code>-Werte bei hochfrequenten Events führen zu Bus-Burst-Zuständen und können die Minimum Delay Time (<code>ComMinimumDelayTime</code>) verletzen, falls diese nicht konsistent mit <code>repetitionPeriod</code> parametriert ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-90178710897ea57e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Templates, Release R22-11).\n</li><li><strong>Architektur-Kontext:</strong> Spezifikation von Übertragungsmustern ereignisgesteuerter Kommunikationsbeziehungen (I-PDU- und Frame-Ebene) im Kommunikations-Cluster (CAN, LIN, FlexRay). Es definiert die Wiederholcharakteristik bei getriggerten Sendeereignissen vor der Transformation in BSW-Generatorkonfigurationen (insb. <code>Com</code>-Stack).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code> (Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Erbt von <code>Describable</code> zur Dokumentation und textuellen Beschreibung des Timing-Elements.\n</li><li>Definiert das Zeitverhalten einer ereignisbasierten Transmission.\n</li><li>Attribut <code>+ numberOfRepetitions: Integer</code>: Anzahl der zusätzlichen Wiederholungen eines I-PDUs nach dem initialen Ereignis-Trigger (<code>0</code> = keine Wiederholung, nur Einzelsendung; <code>n &gt; 0</code> = <code>n</code> Wiederholungen).\n</li></ul>\n</li><li><strong><code>TimeRangeType</code> (Strukturtyp):</strong>\n<ul class=\"fig-list\"><li>Aggregiert über gerichtete Komposition (<code>+repetitionPeriod</code>, Kardinalität <code>0..1</code>).\n</li><li>Attribut <code>+ value: TimeValue</code>: Physikalischer Basiswert der Wiederholperiode als standardisierter Zeitwert.\n</li></ul>\n</li><li><strong><code>TimeRangeTypeTolerance</code> (Abstrakte Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimeRangeType</code> über gerichtete Komposition (<code>+tolerance</code>, Kardinalität <code>0..1</code>).\n</li><li>Dient als polymorphe Basis für Toleranzangaben.\n</li></ul>\n</li><li><strong><code>RelativeTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ relative: Integer</code>: Prozentuale Abweichung bezogen auf <code>value</code> (z. B. Jitter-Toleranz).\n</li></ul>\n</li><li><strong><code>AbsoluteTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ absolute: TimeValue</code>: Absolute zeitliche Abweichung als standardisierter Zeitwert ($\\pm \\Delta t$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Eine Applikations-SWC aktualisiert ein Signal via RTE mit Übertragungseigenschaft <code>TRIGGERED</code> oder <code>TRIGGERED_WITHOUT_REPETITION</code>.\n</li><li><strong>Sendeabfolge:</strong>\n<ol class=\"fig-list\"><li>Initialer Sendeaufruf (<code>PduR_ComTransmit</code> bzw. <code>Com_SendSignal</code>) triggert die erste PDU-Übertragung.\n</li><li>Ist <code>numberOfRepetitions &gt; 0</code>, startet der COM-Stack einen internen zyklischen Wiederholungs-Timer mit Intervall T_rep = repetitionPeriod.value ± tolerance.\n</li><li>Nach Ablauf von T_rep erfolgt die nächste Aussendung, bis exakt <code>numberOfRepetitions</code> Folgeübertragungen abgesetzt wurden.\n</li><li>Trifft während eines laufenden Wiederholungszyklus ein erneutes Event ein, wird der Wiederholzähler gemäß COM-Filter-/Übertragungssemantik entweder re-triggert oder verworfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Transformation in BSW-Konfiguration (COM):</strong>\n<ul class=\"fig-list\"><li>Entspricht direkt den Parametern des BSW-Moduls <code>Com</code> (<code>ComTxModeNumberOfRepetitions</code> und <code>ComTxModeRepetitionPeriod</code> innerhalb von <code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li></ul>\n</li><li><strong>Timing-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><code>TimeRangeType.value</code> muss auf ein ganzzahliges Vielfaches des BSW-Zyklus (<code>Com_MainFunctionTx</code> Raster) abgebildet werden. Abweichungen müssen innerhalb der spezifizierten <code>tolerance</code> (absolut oder relativ) liegen, andernfalls drohen Konfigurationswarnungen oder Jitter im Sende-Task.\n</li></ul>\n</li><li><strong>PDU-Priorisierung &amp; Buslast:</strong>\n<ul class=\"fig-list\"><li>Hohe <code>numberOfRepetitions</code>-Werte bei hochfrequenten Events führen zu Bus-Burst-Zuständen und können die Minimum Delay Time (<code>ComMinimumDelayTime</code>) verletzen, falls diese nicht konsistent mit <code>repetitionPeriod</code> parametriert ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bd6834903fb0b85a", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Templates, Release R23-11).\n</li><li><strong>Architektur-Kontext:</strong> Spezifikation von Übertragungsmustern ereignisgesteuerter Kommunikationsbeziehungen (I-PDU- und Frame-Ebene) im Kommunikations-Cluster (CAN, LIN, FlexRay). Es definiert die Wiederholcharakteristik bei getriggerten Sendeereignissen vor der Transformation in BSW-Generatorkonfigurationen (insb. <code>Com</code>-Stack).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code> (Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Erbt von <code>Describable</code> zur Dokumentation und textuellen Beschreibung des Timing-Elements.\n</li><li>Definiert das Zeitverhalten einer ereignisbasierten Transmission.\n</li><li>Attribut <code>+ numberOfRepetitions: Integer [0..1]</code>: Optionale Angabe der Anzahl zusätzlicher Wiederholungen eines I-PDUs nach dem initialen Ereignis-Trigger (<code>0</code> = keine Wiederholung, nur Einzelsendung; <code>n &gt; 0</code> = <code>n</code> Wiederholungen).\n</li></ul>\n</li><li><strong><code>TimeRangeType</code> (Strukturtyp):</strong>\n<ul class=\"fig-list\"><li>Aggregiert über gerichtete Komposition (<code>+repetitionPeriod</code>, Kardinalität <code>0..1</code>).\n</li><li>Attribut <code>+ value: TimeValue [0..1]</code>: Optionaler physikalischer Basiswert der Wiederholperiode als standardisierter Zeitwert.\n</li></ul>\n</li><li><strong><code>TimeRangeTypeTolerance</code> (Abstrakte Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimeRangeType</code> über gerichtete Komposition (<code>+tolerance</code>, Kardinalität <code>0..1</code>).\n</li><li>Dient als polymorphe Basis für Toleranzangaben.\n</li></ul>\n</li><li><strong><code>RelativeTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ relative: Integer [0..1]</code>: Optionale prozentuale Abweichung bezogen auf <code>value</code> (z. B. Jitter-Toleranz).\n</li></ul>\n</li><li><strong><code>AbsoluteTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ absolute: TimeValue [0..1]</code>: Optionale absolute zeitliche Abweichung als standardisierter Zeitwert ($\\pm \\Delta t$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Eine Applikations-SWC aktualisiert ein Signal via RTE mit Übertragungseigenschaft <code>TRIGGERED</code> oder <code>TRIGGERED_WITHOUT_REPETITION</code>.\n</li><li><strong>Sendeabfolge:</strong>\n<ol class=\"fig-list\"><li>Initialer Sendeaufruf (<code>PduR_ComTransmit</code> bzw. <code>Com_SendSignal</code>) triggert die erste PDU-Übertragung.\n</li><li>Ist <code>numberOfRepetitions &gt; 0</code>, startet der COM-Stack einen internen zyklischen Wiederholungs-Timer mit Intervall T_rep = repetitionPeriod.value ± tolerance.\n</li><li>Nach Ablauf von T_rep erfolgt die nächste Aussendung, bis exakt <code>numberOfRepetitions</code> Folgeübertragungen abgesetzt wurden.\n</li><li>Trifft während eines laufenden Wiederholungszyklus ein erneutes Event ein, wird der Wiederholzähler gemäß COM-Filter-/Übertragungssemantik entweder re-triggert oder verworfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Transformation in BSW-Konfiguration (COM):</strong>\n<ul class=\"fig-list\"><li>Entspricht direkt den Parametern des BSW-Moduls <code>Com</code> (<code>ComTxModeNumberOfRepetitions</code> und <code>ComTxModeRepetitionPeriod</code> innerhalb von <code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li></ul>\n</li><li><strong>Timing-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><code>TimeRangeType.value</code> muss auf ein ganzzahliges Vielfaches des BSW-Zyklus (<code>Com_MainFunctionTx</code> Raster) abgebildet werden. Abweichungen müssen innerhalb der spezifizierten <code>tolerance</code> (absolut oder relativ) liegen, andernfalls drohen Konfigurationswarnungen oder Jitter im Sende-Task.\n</li></ul>\n</li><li><strong>PDU-Priorisierung &amp; Buslast:</strong>\n<ul class=\"fig-list\"><li>Hohe <code>numberOfRepetitions</code>-Werte bei hochfrequenten Events führen zu Bus-Burst-Zuständen und können die Minimum Delay Time (<code>ComMinimumDelayTime</code>) verletzen, falls diese nicht konsistent mit <code>repetitionPeriod</code> parametriert ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-71522cb020eba963", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Templates, Release R23-11).\n</li><li><strong>Architektur-Kontext:</strong> Spezifikation von Übertragungsmustern ereignisgesteuerter Kommunikationsbeziehungen (I-PDU- und Frame-Ebene) im Kommunikations-Cluster (CAN, LIN, FlexRay). Es definiert die Wiederholcharakteristik bei getriggerten Sendeereignissen vor der Transformation in BSW-Generatorkonfigurationen (insb. <code>Com</code>-Stack).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code> (Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Erbt von <code>Describable</code> zur Dokumentation und textuellen Beschreibung des Timing-Elements.\n</li><li>Definiert das Zeitverhalten einer ereignisbasierten Transmission.\n</li><li>Attribut <code>+ numberOfRepetitions: Integer [0..1]</code>: Optionale Angabe der Anzahl zusätzlicher Wiederholungen eines I-PDUs nach dem initialen Ereignis-Trigger (<code>0</code> = keine Wiederholung, nur Einzelsendung; <code>n &gt; 0</code> = <code>n</code> Wiederholungen).\n</li></ul>\n</li><li><strong><code>TimeRangeType</code> (Strukturtyp):</strong>\n<ul class=\"fig-list\"><li>Aggregiert über gerichtete Komposition (<code>+repetitionPeriod</code>, Kardinalität <code>0..1</code>).\n</li><li>Attribut <code>+ value: TimeValue [0..1]</code>: Optionaler physikalischer Basiswert der Wiederholperiode als standardisierter Zeitwert.\n</li></ul>\n</li><li><strong><code>TimeRangeTypeTolerance</code> (Abstrakte Metaklasse):</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimeRangeType</code> über gerichtete Komposition (<code>+tolerance</code>, Kardinalität <code>0..1</code>).\n</li><li>Dient als polymorphe Basis für Toleranzangaben.\n</li></ul>\n</li><li><strong><code>RelativeTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ relative: Integer [0..1]</code>: Optionale prozentuale Abweichung bezogen auf <code>value</code> (z. B. Jitter-Toleranz).\n</li></ul>\n</li><li><strong><code>AbsoluteTolerance</code> (Metaklasse, Subtyp von <code>TimeRangeTypeTolerance</code>):</strong>\n<ul class=\"fig-list\"><li>Attribut <code>+ absolute: TimeValue [0..1]</code>: Optionale absolute zeitliche Abweichung als standardisierter Zeitwert ($\\pm \\Delta t$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ereignis-Trigger:</strong> Eine Applikations-SWC aktualisiert ein Signal via RTE mit Übertragungseigenschaft <code>TRIGGERED</code> oder <code>TRIGGERED_WITHOUT_REPETITION</code>.\n</li><li><strong>Sendeabfolge:</strong>\n<ol class=\"fig-list\"><li>Initialer Sendeaufruf (<code>PduR_ComTransmit</code> bzw. <code>Com_SendSignal</code>) triggert die erste PDU-Übertragung.\n</li><li>Ist <code>numberOfRepetitions &gt; 0</code>, startet der COM-Stack einen internen zyklischen Wiederholungs-Timer mit Intervall T_rep = repetitionPeriod.value ± tolerance.\n</li><li>Nach Ablauf von T_rep erfolgt die nächste Aussendung, bis exakt <code>numberOfRepetitions</code> Folgeübertragungen abgesetzt wurden.\n</li><li>Trifft während eines laufenden Wiederholungszyklus ein erneutes Event ein, wird der Wiederholzähler gemäß COM-Filter-/Übertragungssemantik entweder re-triggert oder verworfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Transformation in BSW-Konfiguration (COM):</strong>\n<ul class=\"fig-list\"><li>Entspricht direkt den Parametern des BSW-Moduls <code>Com</code> (<code>ComTxModeNumberOfRepetitions</code> und <code>ComTxModeRepetitionPeriod</code> innerhalb von <code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li></ul>\n</li><li><strong>Timing-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><code>TimeRangeType.value</code> muss auf ein ganzzahliges Vielfaches des BSW-Zyklus (<code>Com_MainFunctionTx</code> Raster) abgebildet werden. Abweichungen müssen innerhalb der spezifizierten <code>tolerance</code> (absolut oder relativ) liegen, andernfalls drohen Konfigurationswarnungen oder Jitter im Sende-Task.\n</li></ul>\n</li><li><strong>PDU-Priorisierung &amp; Buslast:</strong>\n<ul class=\"fig-list\"><li>Hohe <code>numberOfRepetitions</code>-Werte bei hochfrequenten Events führen zu Bus-Burst-Zuständen und können die Minimum Delay Time (<code>ComMinimumDelayTime</code>) verletzen, falls diese nicht konsistent mit <code>repetitionPeriod</code> parametriert ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d1399657d6a9954a", "to": "FIG-f79e0a688065fc8b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code></strong>: Kardinalität der Kompositionsrolle <code>+repetitionPeriod</code> von <code>1</code> auf <code>0..1</code> geändert; Attributtyp von <code>+ numberOfRepeats</code> von <code>Int</code> auf <code>Integer</code> geändert.\n</li><li><strong><code>RelativeTolerance</code></strong>: Attributtyp von <code>+ relative</code> von <code>Int</code> auf <code>Integer</code> geändert.\n</li></ul>"}, {"from": "FIG-f79e0a688065fc8b", "to": "FIG-d3a69ed97630c286", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code></strong>: Attributname von <code>+ numberOfRepeats</code> in <code>+ numberOfRepetitions</code> geändert.\n</li><li><strong><code>TimeRangeType</code></strong>: Attributtyp von <code>+ value</code> von <code>Float</code> auf <code>TimeValue</code> geändert.\n</li><li><strong><code>AbsoluteTolerance</code></strong>: Attributtyp von <code>+ absolute</code> von <code>Float</code> auf <code>TimeValue</code> geändert.\n</li></ul>"}, {"from": "FIG-d3a69ed97630c286", "to": "FIG-a8bba802d8b91b6e", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>EventControlledTiming</code></strong>: Spezialisiert nun als Subklasse die Metaklasse <code>Describable</code> (angezeigt über den Stereotyp/Kopfvermerk <code>«Describable»</code> bzw. Kursiv-Header <code>Describable</code>).\n</li></ul>"}, {"from": "FIG-a8bba802d8b91b6e", "to": "FIG-8361984e889c0ac3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8361984e889c0ac3", "to": "FIG-c416955f9b8dbb27", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c416955f9b8dbb27", "to": "FIG-90178710897ea57e", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-90178710897ea57e", "to": "FIG-bd6834903fb0b85a", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>EventControlledTiming.numberOfRepetitions</code>: Multiplizität explizit auf <code>[0..1]</code> gesetzt (zuvor implizit bzw. obligatorisch <code>1</code>).\n</li><li>Attribut <code>TimeRangeType.value</code>: Multiplizität explizit auf <code>[0..1]</code> gesetzt.\n</li><li>Attribut <code>RelativeTolerance.relative</code>: Multiplizität explizit auf <code>[0..1]</code> gesetzt.\n</li><li>Attribut <code>AbsoluteTolerance.absolute</code>: Multiplizität explizit auf <code>[0..1]</code> gesetzt.\n</li></ul>"}, {"from": "FIG-bd6834903fb0b85a", "to": "FIG-71522cb020eba963", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
